const items = $input.all();
return items.map(item => {
  const emp = item.json;
  const gross = emp.salary_type === 'hourly'
    ? emp.total_hours * emp.hourly_rate
    : emp.monthly_salary;
  const tax = gross * 0.25;
  const net = gross - tax;
  return { json: { ...emp, gross_pay: gross.toFixed(2), tax: tax.toFixed(2), net_pay: net.toFixed(2) } };
});
